package ro.leo.visual;
import ro.leo.i18n.L;
import android.bluetooth.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import org.json.*;
public final class BluetoothTransfersActivity extends LeoActivity {
 private final Handler timer=new Handler();private boolean resumed,loading,history;private String signature="";private JSONArray entries=new JSONArray();private int selected;
 private final Runnable refresh=new Runnable(){public void run(){if(resumed&&history){load();timer.postDelayed(this,1500);}}};
 protected void onCreate(Bundle b){super.onCreate(b);if(getIntent().getData()!=null||getIntent().hasExtra("many"))devices();else{history=true;begin(L.t("Transferuri Bluetooth"));root.addView(text(L.t("Se încarcă…"),16));footer("","",L.t("Înapoi"));}}
 protected void onResume(){super.onResume();resumed=true;if(history){timer.removeCallbacks(refresh);timer.post(refresh);}}
 protected void onPause(){resumed=false;timer.removeCallbacks(refresh);super.onPause();}
 private void devices(){history=false;BluetoothAdapter adapter=BluetoothAdapter.getDefaultAdapter();if(adapter==null||!adapter.isEnabled()){notice(L.t("Pornește Bluetooth înainte de transfer"));finish();return;}final ArrayList<BluetoothDevice> devices=new ArrayList<BluetoothDevice>(adapter.getBondedDevices());ArrayList<String> labels=new ArrayList<String>();for(BluetoothDevice d:devices)labels.add((d.getName()==null?L.t("Dispozitiv Bluetooth"):d.getName())+"\n"+d.getAddress());list(L.t("Trimite prin Bluetooth"),labels,0,new Choice(){public void pick(final int at){options(L.t("Trimiți fișierele alese?"),new String[]{L.t("Anulează"),L.t("Trimite")},new Choice(){public void pick(int yes){if(yes!=1)return;final ArrayList<Uri> uris=getIntent().getParcelableArrayListExtra("many");final ArrayList<Uri> files=uris==null?new ArrayList<Uri>():new ArrayList<Uri>(uris);if(uris==null)files.add(getIntent().getData());worker.execute(new Runnable(){public void run(){try{BluetoothTransfers.send(BluetoothTransfersActivity.this,devices.get(at).getAddress(),files,getIntent().getType());ui(new Runnable(){public void run(){history=true;signature="";timer.post(refresh);}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Transferul Bluetooth nu a putut fi pornit"));}});}}});}});}},L.t("Asociază dispozitiv"),new Runnable(){public void run(){startActivity(new Intent(BluetoothTransfersActivity.this,ConnectivityActivity.class).putExtra("kind","bluetooth"));}});if(devices.isEmpty())notice(L.t("Asociază mai întâi celălalt telefon"));}
 static String status(int value){return value==200?L.t("Finalizat"):value>=400?L.t("Eșuat")+" · "+value:value==192?L.t("În transfer"):L.t("În așteptare");}
 private void load(){if(loading)return;loading=true;worker.execute(new Runnable(){public void run(){try{final JSONArray rows=BluetoothTransfers.run(BluetoothTransfersActivity.this,"list",null).getJSONArray("rows");ui(new Runnable(){public void run(){loading=false;if(!history)return;ArrayList<String> labels=new ArrayList<String>();StringBuilder ids=new StringBuilder();for(int n=0;n<rows.length();n++){JSONObject row=rows.optJSONObject(n);ids.append(row.optLong("id")).append(',');int percent=BluetoothTransfers.percent(row.optLong("current"),row.optLong("total"));String name=row.optString("name");if(name.isEmpty())name=new File(row.optString("file")).getName();labels.add((row.optInt("direction")==1?"↓ ":"↑ ")+(name.isEmpty()?L.t("Fișier Bluetooth"):name)+"\n"+(row.optInt("direction")==1&&row.optInt("confirm")==0?L.t("Acceptă primirea"):status(row.optInt("status")))+(percent<0?"":" · "+percent+"%"));}String next=ids.toString();if(next.equals(signature)&&replaceRows(L.t("Transferuri Bluetooth"),labels)){entries=rows;return;}signature=next;entries=rows;list(L.t("Transferuri Bluetooth"),labels,Math.min(selected,Math.max(0,rows.length()-1)),new Choice(){public void pick(int n){selected=n;actions(entries.optJSONObject(n));}},L.t("Actualiz."),new Runnable(){public void run(){load();}});back=null;}});}catch(Exception e){ui(new Runnable(){public void run(){loading=false;if(history){history=false;begin(L.t("Transferuri Bluetooth"));root.addView(text(L.t("Serviciul de transfer Bluetooth nu este disponibil. Verifică Bluetooth și încearcă din nou."),16));left=new Runnable(){public void run(){history=true;timer.post(refresh);}};footer(L.t("Reîncearcă"),"",L.t("Înapoi"));}}});}}});}
 private void actions(final JSONObject row){if(row==null)return;final long id=row.optLong("id");if(row.optInt("direction")==1&&row.optInt("confirm")==0&&row.optInt("status")<200){options(L.t("Fișier Bluetooth primit"),new String[]{L.t("Acceptă"),L.t("Refuză")},new Choice(){public void pick(int n){action(n==0?"accept":"reject",id);}});}else if(row.optInt("status")<200){options(L.t("Anulezi transferul?"),new String[]{L.t("Păstrează"),L.t("Anulează transferul")},new Choice(){public void pick(int n){if(n==1)action("cancel",id);}});}else if(row.optInt("status")==200&&row.optInt("direction")==1){final File file=new File(row.optString("file"));options(file.getName(),new String[]{L.t("Arată în Fișiere"),L.t("Deschide")},new Choice(){public void pick(int n){try{if(n==0)startActivity(new Intent(BluetoothTransfersActivity.this,FilesActivity.class).putExtra("folder",file.getParent()).putExtra("select_file",file.getPath()));else ShareHubActivity.view(BluetoothTransfersActivity.this,LeoFileProvider.uri(BluetoothTransfersActivity.this,file),row.optString("mime","application/octet-stream"));}catch(Exception e){notice(L.t("Fișier inaccesibil"));}}});}else notice(status(row.optInt("status")));}
 private void action(final String operation,final long id){worker.execute(new Runnable(){public void run(){try{BluetoothTransfers.run(BluetoothTransfersActivity.this,operation,""+id);ui(new Runnable(){public void run(){signature="";load();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Transferul nu mai permite această acțiune"));}});}}});}
}
